package com.opensocket.aievent.core.iam.authentication.domain;
import java.time.Instant;import java.util.Objects;import java.util.Optional;
public record RootBootstrapState(Status status,boolean passwordConfigured,boolean mfaConfigured,boolean tenantCreated,boolean tenantAdminCreated,Optional<Instant> completedAt,long version){public RootBootstrapState{Objects.requireNonNull(status,"status");completedAt=completedAt==null?Optional.empty():completedAt;if(status==Status.COMPLETED&&(!passwordConfigured||!mfaConfigured||!tenantCreated||!tenantAdminCreated||completedAt.isEmpty()))throw new IllegalArgumentException("completed bootstrap requires all steps");if(version<1)throw new IllegalArgumentException("version must be positive");}public static RootBootstrapState required(){return new RootBootstrapState(Status.REQUIRED,false,false,false,false,Optional.empty(),1);}public RootBootstrapState markPasswordConfigured(){return next(true,mfaConfigured,tenantCreated,tenantAdminCreated);}public RootBootstrapState markMfaConfigured(){return next(passwordConfigured,true,tenantCreated,tenantAdminCreated);}public RootBootstrapState markTenantCreated(){return next(passwordConfigured,mfaConfigured,true,tenantAdminCreated);}public RootBootstrapState markTenantAdminCreated(){return next(passwordConfigured,mfaConfigured,tenantCreated,true);}public RootBootstrapState complete(Instant at){if(!passwordConfigured||!mfaConfigured||!tenantCreated||!tenantAdminCreated)throw new AuthenticationDomainException(AuthenticationReasonCode.ROOT_OPERATION_NOT_ALLOWED,"Bootstrap steps are incomplete");return new RootBootstrapState(Status.COMPLETED,true,true,true,true,Optional.of(at),version+1);}private RootBootstrapState next(boolean p,boolean m,boolean t,boolean a){if(status==Status.COMPLETED)throw new AuthenticationDomainException(AuthenticationReasonCode.ROOT_BOOTSTRAP_ALREADY_COMPLETED,"Root bootstrap already completed");return new RootBootstrapState(Status.IN_PROGRESS,p,m,t,a,Optional.empty(),version+1);}public enum Status{REQUIRED,IN_PROGRESS,COMPLETED}}
